    if not entries:
        return IngestionResult(
            status=IngestionStatus.WAITING_FOR_AGENT_ACTIVITY,
            checkpoints=[],
            notes=[
                "No pending checkpoints found. Pending checkpoints are "
                "created automatically during active agent sessions."
