:root {
  color-scheme: dark;
  --bg: #0b0e14;
  --surface: #131824;
  --border: #232b3d;
  --text: #e6e9f0;
  --text-dim: #8b93a7;
  --accent: #5eead4;
  --danger: #f87171;
  --warn: #fbbf24;
  font-family: 'Segoe UI', system-ui, sans-serif;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  background: var(--bg);
  color: var(--text);
}

.control-tower {
  min-height: 100vh;
  padding: 2rem clamp(1rem, 5vw, 4rem);
}

header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 2rem;
}

header h1 {
  font-size: 1.5rem;
  margin: 0;
  letter-spacing: 0.02em;
}

.connection-badge {
  font-size: 0.85rem;
  padding: 0.3rem 0.7rem;
  border-radius: 999px;
  border: 1px solid var(--border);
}

.connection-live {
  color: var(--accent);
  border-color: var(--accent);
}

.connection-connecting {
  color: var(--warn);
  border-color: var(--warn);
}

.connection-disconnected {
  color: var(--danger);
  border-color: var(--danger);
  animation: pulse 1.4s ease-in-out infinite;
}

.repo-form {
  display: flex;
  align-items: center;
  gap: 0.6rem;
  margin-bottom: 1.5rem;
  flex-wrap: wrap;
}

.repo-form input {
  flex: 1;
  min-width: 260px;
  background: var(--surface);
  border: 1px solid var(--border);
  color: var(--text);
  padding: 0.5rem 0.75rem;
  border-radius: 8px;
  font-size: 0.9rem;
}

.repo-form input:focus {
  outline: none;
  border-color: var(--accent);
}

.repo-form button {
  background: var(--accent);
  color: #04211d;
  border: none;
  padding: 0.5rem 1rem;
  border-radius: 8px;
  font-weight: 600;
  cursor: pointer;
}

.repo-form button:disabled {
  opacity: 0.6;
  cursor: default;
}

.active-repo-label {
  color: var(--text-dim);
  font-size: 0.85rem;
  font-family: 'Cascadia Code', 'Consolas', monospace;
}

.error-banner {
  background: rgba(248, 113, 113, 0.1);
  border: 1px solid var(--danger);
  color: var(--danger);
  padding: 0.75rem 1rem;
  border-radius: 8px;
  margin-bottom: 1.5rem;
  font-size: 0.9rem;
}

.loading {
  color: var(--text-dim);
}

.waiting-state {
  text-align: center;
  padding: 4rem 1rem;
  color: var(--text-dim);
  border: 1px dashed var(--border);
  border-radius: 16px;
}

.waiting-state h2 {
  color: var(--text);
  letter-spacing: 0.05em;
  font-size: 1.1rem;
}

.pulse-dot {
  width: 12px;
  height: 12px;
  border-radius: 50%;
  background: var(--warn);
  margin: 0 auto 1rem;
  animation: pulse 1.4s ease-in-out infinite;
}

@keyframes pulse {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.35; }
}

.agent-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(320px, 1fr));
  gap: 1.25rem;
}

.agent-node {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 14px;
  padding: 1.25rem 1.5rem;
}

.agent-node-header {
  display: flex;
  align-items: center;
  gap: 0.6rem;
  margin-bottom: 0.75rem;
}

.agent-node-header h2 {
  font-size: 1.05rem;
  margin: 0;
  flex: 1;
}

.status-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
}

.status-active {
  background: var(--accent);
  box-shadow: 0 0 8px var(--accent);
}

.status-badge {
  font-size: 0.7rem;
  letter-spacing: 0.05em;
  color: var(--text-dim);
  border: 1px solid var(--border);
  border-radius: 999px;
  padding: 0.15rem 0.5rem;
